from pathlib import Path
from html import escape
out=Path('outputs/context-diagram')
a=['<svg xmlns="http://www.w3.org/2000/svg" width="1500" height="1150" viewBox="0 0 1500 1150" role="img" aria-labelledby="title desc"><title id="title">StudentShield web application context diagram</title><desc id="desc">One process exchanges data with Student, Counselor, Super Administrator, the external ML service, and Parent or Guardian. Scope: vent screening and bullying reporting.</desc><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="8" markerHeight="8" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10 Z" fill="#111"/></marker></defs><rect width="1500" height="1150" fill="white"/><g font-family="Times New Roman, Times, serif" fill="#111" font-size="25">']
def text(x,y,lines,size=25,bold=False,anchor="middle"):
 a.append(f'<text x="{x}" y="{y}" text-anchor="{anchor}" font-size="{size}"'+(' font-weight="bold"' if bold else '')+'>')
 for i,s in enumerate(lines):a.append(f'<tspan x="{x}" dy="{0 if i==0 else 30}">{escape(s)}</tspan>')
 a.append('</text>')
def box(x,y,w,h,lines):
 a.append(f'<rect x="{x}" y="{y}" width="{w}" height="{h}" fill="white" stroke="#111" stroke-width="2.5"/>');text(x+w/2,y+h/2-(len(lines)-1)*15+8,lines,27,True)
def arrow(x1,y1,x2,y2):a.append(f'<path d="M{x1} {y1} L{x2} {y2}" fill="none" stroke="#111" stroke-width="2.5" marker-end="url(#arrow)"/>')
