arrow(240,460,600,460);text(420,386,['Credentials; vent text and','parent-hiding selection;','incident details and evidence'],24)
arrow(600,650,240,650);text(420,576,['Authentication results;','submission confirmations','and report status'],24)
arrow(1260,420,900,420);text(1080,346,['Credentials; review requests;','verification / rejection decisions;','case notes and status updates'],23)
arrow(900,520,1260,520);text(1080,476,['Case records, screening results,','and counselor notifications'],23)
arrow(1260,700,900,700);text(1080,626,['Credentials; account / role changes;','case decisions and updates;','audit and record requests'],23)
