a.append('</g></svg>');svg=''.join(a);(out/'StudentShield Context Diagram.svg').write_text(svg,encoding='utf-8')
caption='Figure 2. Context Diagram of StudentShield Vent Screening and Bullying Reporting'
paragraph='Figure 2 presents the StudentShield web application as a single process for vent screening and bullying reporting. Students supply credentials, vents, parent-hiding selections, incident details, and optional evidence. The application exchanges current vent text, a student identifier, and prior risk labels and timestamps with the external machine learning service. Counselors review cases and provide verification decisions, notes, and status updates. Super administrators also manage accounts and roles and access audit records. Parents and guardians receive notifications only when the applicable rules permit. This diagram is limited to these workflows; it does not represent the online meeting module.'
note='[1] High-risk vents trigger counselor notification attempts. Critical vents may also trigger parent notifications, subject to parent hiding, available contact details, and applicable cooldowns. Bullying intake alerts counselors; staff verification precedes incident notifications to resolved victim or alleged-bully parent contacts. A second false-report strike has a separate reporter-parent notification path. Message delivery is not guaranteed.'
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>StudentShield — Context Diagram</title><style>
*{box-sizing:border-box}body{margin:0;background:#eef1f5;color:#162033;font:16px/1.5 system-ui,sans-serif}main{max-width:1320px;margin:auto;padding:24px}header{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}h1{font-size:24px;margin:0}header p{margin:5px 0 16px;color:#465269}nav{display:flex;gap:8px;flex-wrap:wrap}button{font:inherit;padding:10px 16px;border:1px solid #34445d;border-radius:5px;background:white;color:#162033;cursor:pointer}button:first-child{background:#162033;color:white}button:focus-visible,a:focus-visible{outline:3px solid #337dd6;outline-offset:3px}figure{margin:20px 0;background:white;padding:20px;border:1px solid #c4cbd5}svg{display:block;width:100%;height:auto}figcaption{font:12pt/1.3 'Times New Roman',serif;text-align:center;margin-top:16px}.copy{background:white;padding:24px;margin-top:20px;border:1px solid #c4cbd5}.copy h2{font-size:18px;margin-top:0}.paper{font:12pt/1.5 'Times New Roman',serif;text-align:justify}.note{font-size:14px}details{margin-top:24px}a{color:#174c93}li{margin-bottom:10px}@media print{@page{size:A4 landscape;margin:12mm}body{background:white}main{padding:0}header,.copy,details{display:none}figure{border:0;padding:0;margin:0}svg{height:155mm;width:100%}figcaption{margin-top:4mm}}@media(max-width:600px){main{padding:12px}figure{padding:6px}.copy{padding:16px}}
</style><main><header><div><h1>StudentShield context diagram</h1><p>Figure 2 · Web application boundary · Vent screening and bullying reporting</p></div><nav aria-label="Export diagram"><button id="png">Download PNG</button><button id="svg">Download SVG</button><button id="print">Print / Save PDF</button></nav></header><figure>'''+svg+'<figcaption>'+caption+'</figcaption></figure><section class="copy"><h2>Copy beneath the figure</h2><p class="paper">'+paragraph+'</p><p class="paper">'+note+'''</p></section><details><summary>Research, boundary decisions, and verification</summary><ul><li>One process represents the selected application boundary; external entities connect only through named, directional data flows. Internal stores and decision diamonds are omitted.</li><li>The custom ML service is external to this web-application boundary, although it belongs to the wider StudentShield project. MySQL, encryption, fallback rules, and internal case modules are not external entities. Parents are recipients, not authenticated portal users.</li><li>This is a logical context view. SMTP and SMS are delivery mechanisms for the recipient flows, not extra business actors. Hosting vendors and network infrastructure belong in the architecture diagram. The meeting workflow is explicitly outside this figure’s scope.</li><li>Role and flow checks: VentController.php, BullyReportController.php, AdminController.php, and the supplied capstone. Repository review does not establish live delivery performance or completed evaluation.</li><li>Conventions: <a href="https://online.visual-paradigm.com/knowledge/system-contextdiagram/what-is-system-context-diagram/">Visual Paradigm: system context diagrams</a>; <a href="https://www.visual-paradigm.com/support/documents/vpuserguide/1284/992/36119_dataflowdiag.html">DFD connection rules</a>.</li></ul><p>In Google Docs, insert the PNG and keep the caption and explanatory paragraphs as editable text. Use the SVG when a vector format is supported. Preserve the capstone template’s margins and borders.</p></details><p id="status" role="status"></p></main><script>
const svg=document.querySelector('svg');function save(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}function source(){return new XMLSerializer().serializeToString(svg)}document.querySelector('#svg').onclick=()=>save(new Blob([source()],{type:'image/svg+xml'}),'StudentShield Context Diagram.svg');document.querySelector('#print').onclick=()=>window.print();document.querySelector('#png').onclick=()=>{const url=URL.createObjectURL(new Blob([source()],{type:'image/svg+xml'})),im=new Image();im.onload=()=>{const c=document.createElement('canvas');c.width=3000;c.height=2300;const ctx=c.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(im,0,0,c.width,c.height);URL.revokeObjectURL(url);c.toBlob(b=>{save(b,'StudentShield Context Diagram.png');document.querySelector('#status').textContent='PNG exported. Insert it into Google Docs, then copy the caption and explanation.'},'image/png')};im.onerror=()=>{URL.revokeObjectURL(url);document.querySelector('#status').textContent='PNG export failed. Use the SVG download or print instead.'};im.src=url};
</script></html>'''
(out/'index.html').write_text(html,encoding='utf-8')
(out/'Caption and explanation.txt').write_text(caption+'\n\n'+paragraph+'\n\n'+note,encoding='utf-8')
